import re

def to_seconds(s):
    """Convert a duration string to seconds."""
    h = m = s = 0
    for part in re.findall(r'(\d+)([hms])', s):
        num, unit = part
        num = int(num)
        if unit == 'h':
            h += num
        elif unit == 'm':
            m += num
        elif unit == 's':
            s += num
    return h * 3600 + m * 60 + s

