    """Convert seconds to a human-readable duration string."""
    if n == 0:
        return '0s'
    hours = n // 3600
    minutes = (n % 3600) // 60
    seconds = n % 60
    parts = []
    if hours:
        parts.append(f"{hours}h")
    if minutes:
        parts.append(f"{minutes}m")
    if seconds:
        parts.append(f"{seconds}s")
    return "".join(parts)

